function sameAs(want, err, out) {
  if (want && want.error) {
    expect(err).to.be.an(Error);
    expect(err.message).to.contain(want.error);
    return;
  }
  if (err) {
    throw err;
  }
  expect(out).to.equal(want);
}

function attempt(fn) {
  try {
    return [null, fn()];
  } catch (e) {
    return [e];
  }
}

Object.keys(flavors).forEach(function (name) {
  var flavor = flavors[name], Ctor = flavor.lib[flavor.ctor];

  describe('nested blocks (' + name + ')', function () {
    flavor.shapes.forEach(function (s) {
      var mem = flavor.lib.loaders.memory(s.files, '/');

      it(s.id + ' sync: ' + s.title, function () {
        var r = attempt(function () {
          return new Ctor({ loader: mem, cache: false }).renderFile('/t.html', {});
        });
        sameAs(s.sync, r[0], r[1]);
      });

      it(s.id + ' sync, parents cached: ' + s.title, function () {
        var engine = new Ctor({ loader: mem });
        Object.keys(s.files).forEach(function (file) {
          if (file !== '/t.html') {
            attempt(function () { engine.compileFile(file); });
          }
        });
        var r = attempt(function () { return engine.renderFile('/t.html', {}); });
        sameAs(s.sync, r[0], r[1]);
      });

      it(s.id + ' async: ' + s.title, function (done) {
        var loader = { async: true, resolve: mem.resolve, load: function (id, cb) {
          setImmediate(function () {
            var src;
            try { src = mem.load(id); } catch (e) { cb(e); return; }
            cb(null, src);
          });
        } };
        new Ctor({ loader: loader, cache: false }).renderFile('/t.html', {}, function (err, out) {
          try {
            sameAs(s.async, err, out);
          } catch (e) {
            done(e);
            return;
          }
          done();
        });
      });
    });
  });
});
